        }))?;
        let offset = cursor_offset(
            "wit_find_repositories",
            None,
            &fingerprint,
            args.cursor.as_deref(),
        )?;
        let fetch_limit = (offset + max_items + 1).min(MAX_GITHUB_REPOS);
        let results = GitHubSearchClient::new()
